\begin{theorem}
For all $\theta$, $\sin^2 \theta + \cos^2 \theta = 1$.
\end{theorem}

\begin{proof}
The point $(\cos \theta, \sin \theta)$ lies on the unit circle
$x^2 + y^2 = 1$; substituting the coordinates gives
\begin{align}
  \cos^2 \theta + \sin^2 \theta &= 1.
\end{align}
\end{proof}
